/* DanceCube TXT conversion adapted from user-supplied MC2TXT by JiangQiYan713. */
(function(root){'use strict';const C=root.DCCore,enc=text=>new TextEncoder().encode(text),dec=data=>new TextDecoder().decode(data);
function mergeLines(lines){const groups=new Map();for(const line of lines){const p=line.split('-'),key=p.slice(1).join('-');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(+p[0]);}return[...groups].map(([key,cols])=>cols.sort((a,b)=>b-a).join('')+'-'+key);}
function toTXT(input,{merge=true,precision=2}={}){const ch=C.validateChart(input);if(!ch.notes.length)throw Error('空谱面没有可导出的音符');const first=ch.notes[0].beat,base=ch.bpm,firstConverted=C.rawTime(ch,first)*base/60,convert=b=>C.rawTime(ch,b)*base/60-firstConverted,format=x=>(Math.abs(x)<.5*10**-precision?0:x).toFixed(precision),lines=ch.notes.map(n=>`${n.lane+1}-${format(convert(n.beat))}`+(n.end!==null?'-'+format(convert(n.end)):'')),sv=ch.effects.filter(e=>'scroll'in e).map(e=>`${format(convert(C.beatValue(e.beat)))},${e.scroll}`);
 return{normal:(merge?mergeLines(lines):lines).join('\n'),sv:sv.join('\n'),baseBpm:base,startTime:C.beatToTime(ch,first),firstBeat:first,firstConverted,merge,precision};}
function parseTXT(text){const notes=[],re=/^([1-6]{1,6})-([-+]?(?:\d+(?:\.\d*)?|\.\d+))(?:-([-+]?(?:\d+(?:\.\d*)?|\.\d+)))?$/;for(const [i,raw]of text.replace(/^\uFEFF/,'').split(/\r?\n/).entries()){const row=raw.trim();if(!row||row.startsWith('#'))continue;const m=row.match(re);if(!m)throw Error('TXT 第 '+(i+1)+' 行格式无效');const lanes=[...m[1]].map(Number);if(new Set(lanes).size!==lanes.length)throw Error('TXT 第 '+(i+1)+' 行轨道重复');const beat=+m[2],end=m[3]===undefined?null:+m[3];if(!Number.isFinite(beat)||end!==null&&(!Number.isFinite(end)||end<beat))throw Error('TXT 拍数或长条区间无效');for(const lane of lanes)notes.push({id:C.uid(),lane:lane-1,relative:beat,relativeEnd:end,txtChord:m[1].length>1});}if(!notes.length)throw Error('TXT 没有音符');return notes;}
function parseSV(text){const out=[];for(const [i,raw]of text.replace(/^\uFEFF/,'').split(/\r?\n/).entries()){const line=raw.trim();if(!line||line.startsWith('#'))continue;const p=line.split(',').map(Number);if(p.length!==2||!p.every(Number.isFinite))throw Error('SV 第 '+(i+1)+' 行格式无效');out.push({relative:p[0],scroll:p[1]});}return out;}
function fromTXT(normal,sv='',options={}){const bpm=+options.bpm,startTime=+options.startTime;if(!(bpm>0&&bpm<=2000)||!Number.isFinite(startTime))throw Error('TXT 不包含 BPM 和起始时间，需先填写');const source=options.source,ch=C.validateChart({id:C.uid(),name:options.name||'Dance Cube Lv.'+(options.level??12),level:options.level??12,tier:options.tier,creator:options.creator||'',bpm:source?.bpm||bpm,timings:source?.timings||[],offset:source?.offset??-startTime*1000,audioBeat:source?.audioBeat||0,audioName:source?.audioName||'',backgroundName:source?.backgroundName||'',notes:[],effects:[]});const origin=source?C.rawTime(ch,source.firstBeat):0,convert=r=>C.rawBeat(ch,origin+r*60/bpm);
 ch.notes=parseTXT(normal).map(n=>({id:n.id,lane:n.lane,beat:convert(n.relative),end:n.relativeEnd===null?null:convert(n.relativeEnd),txtChord:n.txtChord}));ch.effects=parseSV(sv).map(e=>({beat:C.beatArray(Math.max(0,convert(e.relative))),scroll:e.scroll}));ch.txtMerge=options.merge!==undefined?options.merge:ch.notes.some(n=>n.txtChord);return C.validateChart(ch);}
function txtPack(song,charts,{merge=true}={}){const files=[],manifest={format:'dc-txtpack-1',song,charts:[]},names=new Set();for(const ch of charts){let difficulty=String(ch.level);if(names.has(difficulty))difficulty+='-'+root.DCProject.fileName(ch.name);let suffix=2,original=difficulty;while(names.has(difficulty))difficulty=original+'-'+suffix++;names.add(difficulty);const name=root.DCProject.fileName(song.title)+'-'+difficulty,converted=toTXT(ch,{merge}),source={bpm:ch.bpm,timings:ch.timings,offset:ch.offset,audioBeat:ch.audioBeat,audioName:ch.audioName,backgroundName:ch.backgroundName,firstBeat:converted.firstBeat};files.push({name:name+'.txt',data:enc(converted.normal)},{name:name+'-sv.txt',data:enc(converted.sv)});manifest.charts.push({name:ch.name,level:ch.level,tier:ch.tier,creator:ch.creator,filename:name+'.txt',svFilename:name+'-sv.txt',bpm:converted.baseBpm,startTime:converted.startTime,merge,precision:2,source});}files.push({name:'dc-txtpack.json',data:enc(JSON.stringify(manifest,null,2))});return{files,manifest};}
function readTXTpack(files,options){const manifestFile=files.find(f=>/(^|\/)dc-txtpack.json$/i.test(f.name));if(manifestFile){const m=JSON.parse(dec(manifestFile.data));if(m.format!=='dc-txtpack-1'||!Array.isArray(m.charts))throw Error('TXT 回读信息无效');const dir=manifestFile.name.slice(0,manifestFile.name.lastIndexOf('/')+1);return{song:m.song,charts:m.charts.map(info=>{const normal=files.find(f=>f.name===dir+info.filename),sv=files.find(f=>f.name===dir+info.svFilename);if(!normal)throw Error('TXT 谱面文件缺失：'+info.filename);return fromTXT(dec(normal.data),sv?dec(sv.data):'',info);})};}
 const normal=files.filter(f=>/\.txt$/i.test(f.name)&&!/-sv\.txt$/i.test(f.name));return{song:{title:options?.title||normal[0]?.name.replace(/\.txt$/i,'')||'Untitled',artist:''},charts:normal.map(f=>{const sv=files.find(v=>v.name===f.name.replace(/\.txt$/i,'-sv.txt'));return fromTXT(dec(f.data),sv?dec(sv.data):'',{...options,level:+(f.name.match(/[-_](\d+(?:\.\d+)?)\.txt$/i)?.[1]??options?.level??12),name:f.name.replace(/\.txt$/i,'')});})};}
root.DCFormats={toTXT,fromTXT,parseTXT,parseSV,mergeLines,txtPack,readTXTpack};
})(typeof window==='undefined'?globalThis:window);
